import RNA, random, time
target='((...((....((.....((.........((..............................))...............)).........)).......))....))....'
n=len(target)
pairs=[]
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs.append((j,i))
openidx={p[0] for p in pairs}
closeidx={p[1] for p in pairs}
paired=openidx|closeidx
def score(ss):
    return sum(1 for a,b in zip(ss,target) if a!=b)
def init():
    seq=['A']*n
    for (i,j) in pairs:
        seq[i]='G'; seq[j]='C'
    return ''.join(seq)
# simulated annealing: mutate, accept if MFE closer
seq=list(init())
def mut(seq):
    i=random.randrange(n)
    if i in openidx:
        j=dict(pairs)[i]
        seq[i],seq[j]='G','C'
    elif i in closeidx:
        pass
    else:
        seq[i]=random.choice('ACGU')
def fold(seq):
    s=''.join(seq)
    fc=RNA.fold_compound(s)
    ss,_=fc.mfe()
    return ss
cur=list(init())
cur_ss=fold(cur)
cur_d=score(cur_ss)
best=list(cur);best_d=cur_d
t0=time.time()
T=2.0
import math
while time.time()-t0<100:
    cand=list(cur)
    # mutate a few
    for _ in range(random.randint(1,3)):
        mut(cand)
    css=fold(cand)
    d=score(css)
    if d<=cur_d or random.random()<math.exp(-(d-cur_d)/max(T,0.01)):
        cur=cand;cur_d=d;cur_ss=css
    if d<best_d:
        best_d=d;best=list(cand)
    T*=0.997
print(best_d)
print(''.join(best))
